sources.implementation:
void settle(struct claim *claim) {
    struct account *account = running_account();
    if (claim->account != account) return;
    lock(&account->mutex);
    account->pending = 0;
    unlock(&account->mutex);
}

void record_execution(struct claim *claim) {
    struct account *account = running_account();
    account->executions++;
}

